  ('0980cc58-8d0c-4f62-a2a0-9b8d8bb91e0e', '17d0d942-72f6-4f7d-adbc-949608f409db', 9,
   '[{"domain": "Van persoon naar rechtspersoon", "subdomain": "Persoonlijke financiële zelfredzaamheid"}, {"domain": "Van persoon naar rechtspersoon", "subdomain": "Van eenmanszaak naar rechtspersoon"}]'::jsonb,
   '["arbeidsovereenkomst voor onbepaalde tijd", "eenmanszaak", "continuïteit inkomen", "zekerheid voor de bank", "hypothecaire lening"]'::jsonb,
   $$Uitleggen waarom een vast dienstverband meer zekerheid geeft aan de bank dan een eenmanszaak.$$,
   $$bedrijfseconomie-havo-2021-ii-robin-vermeer-vraag9.png$$, $$2p 9 Leg uit dat de arbeidsovereenkomst van Robin vergeleken met de rechtsvorm van Floor, de bank een grotere financiële zekerheid geeft met betrekking tot het ontvangen van de betalingsverplichtingen. Betrek zowel Robin als Floor in het antwoord.$$, array['e26e4f14-97f3-4685-b932-4a2b1883d970', '386e02e7-6aad-4951-8095-883b66ccb2bd', 'f2e30e55-8445-4e53-8753-0e56b20f3655', '298e75d6-d3f6-47b5-8513-ed7626b7677f', 'bc8e3183-624f-4285-86b9-5c5b46fa1236']::uuid[]),
